function renderCadastro(){return`
        <h1>Ficha de Registro de Novo Apoiador</h1>
        <p>Preencha os campos abaixo para formalizar o seu vínculo com a nossa organização.</p>

        <form action="#" id="form-cadastro">
            <fieldset>
                <legend>Dados Pessoais</legend>
                <div class="campo-validacao">
                    <label for="nome">Nome Completo:</label>
                    <input type="text" id="nome" name="nome" placeholder="Digite seu nome completo" required>
                    <span class="mensagem-erro">Por favor, preencha este campo.</span>
                </div>                
                <div class="campo-validacao">
                    <label for="email">E-mail:</label>
                    <input type="email" id="email" name="email" placeholder="exemplo@email.com" required>
                    <span class="mensagem-erro">Insira um endereço de e-mail válido.</span>
                </div>                
                <div class="campo-validacao">
                    <label for="telefone">Telefone:</label>
                    <input type="tel" id="telefone" name="telefone" placeholder="00000-0000" required pattern="(?:\\(?\\d{2}\\)?\\s?)?\\d{4,5}-?\\d{4}">
                    <span class="mensagem-erro">Respeite o formato de telefone válido! (Use: 00 0000-0000).</span>
                </div>
                <div class="campo-validacao">
                    <label for="nascimento">Data de Nascimento:</label>
                    <input type="date" id="nascimento" name="nascimento" required>
                    <span class="mensagem-erro">Por favor, preencha este campo.</span>
                </div>
                <div class="campo-validacao">
                    <label for="cpf">CPF:</label>
                    <input type="text" id="cpf" name="cpf" placeholder="000.000.000-00" required pattern="\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}">
                    <span class="mensagem-erro">Respeite o formato de CPF válido! (Use: 000.000.000-00).</span>
                </div>				
            </fieldset>

            <fieldset>
                <legend>Endereço Residencial</legend>
                <div class="campo-validacao">
                    <label for="cep">CEP:</label>
                    <input type="text" id="cep" name="cep" placeholder="00000-000" required pattern="\\d{5}-\\d{3}">
                    <span class="mensagem-erro">Respeite o formato de CEP válido! (Use: 00000-000).</span>
                </div>
                <div class="campo-validacao">
                    <label for="num_compl">Número e Complemento:</label>
                    <input type="text" id="num_compl" name="num_compl" placeholder="000 ap.00 bl0" required>
                    <span class="mensagem-erro">Por favor, preencha este campo.</span>
                </div>
            </fieldset>

            <fieldset>
                <legend>Perfil de Interesse</legend>
                <p>Como você deseja colaborar com a ONG Mãos que Acolhem?</p>
                <p>
                    <input type="radio" id="opcao_voluntario" name="interesse" value="voluntariado" required>
                    <label for="opcao_voluntario">Desejo fazer Trabalho Voluntário</label>
                </p>
                <p>
                    <input type="radio" id="opcao_doador" name="interesse" value="financeiro">
                    <label for="opcao_doador">Desejo fazer Contribuição Financeira</label>
                </p>
                <p>
                    <input type="radio" id="opcao_material" name="interesse" value="material">
                    <label for="opcao_material">Desejo fazer Contribuição Material</label>
                </p>
            </fieldset>
            <p>
                <button type="submit" class="btn-enviar-form">Enviar Registro</button>
            </p>
        </form>

        <!-- Estrutura do Modal de Contingência Acessível (Caso o SweetAlert falhe) -->
        <div id="modal-sucesso" class="modal-overlay" aria-hidden="true" role="dialog" aria-labelledby="modal-titulo">
            <div class="modal-feedback-sucesso">
                <button type="button" id="btn-fechar" class="btn-fechar-modal" aria-label="Fechar janela de confirmação">&times;</button>
                <div class="wrapper-logo-interativo">
                    <img src="imagens/logo.png" alt="Logotipo oficial da ONG Mãos que Acolhem" class="logo-sucesso">
                </div>
                <h2 id="modal-titulo">Cadastro Enviado!</h2>
                <p>Seus dados foram salvos com integridade via SPA.</p>
                <div class="container-badges">
                    <span class="badge badge-apoio">Apoiador Ativo</span>
                    <span class="badge badge-status">Aguardando Triagem</span>
                </div>
                <div class="alerta-informativo">
                    <strong>Informação:</strong> 
                    <p>Enviamos as instruções para o seu e-mail.</p>
                </div>
                <a href="#inicio" class="btn-voltar-inicio">Voltar para o Início</a>
            </div>
        </div>
    `}window.inicializarCadastro=function(){const formulario=document.getElementById("form-cadastro");if(!formulario)return;const campos=formulario.querySelectorAll("input[required]");const dadosSalvosString=localStorage.getItem("cadastroApoiador");if(dadosSalvosString){try{const dadosDoApoiador=JSON.parse(dadosSalvosString);if(dadosDoApoiador.nome)document.getElementById("nome").value=dadosDoApoiador.nome;if(dadosDoApoiador.email)document.getElementById("email").value=dadosDoApoiador.email;if(dadosDoApoiador.telefone)document.getElementById("telefone").value=dadosDoApoiador.telefone;if(dadosDoApoiador.nascimento)document.getElementById("nascimento").value=dadosDoApoiador.nascimento;if(dadosDoApoiador.cpf)document.getElementById("cpf").value=dadosDoApoiador.cpf;if(dadosDoApoiador.cep)document.getElementById("cep").value=dadosDoApoiador.cep;if(dadosDoApoiador.num_compl)document.getElementById("num_compl").value=dadosDoApoiador.num_compl;if(dadosDoApoiador.interesse){const radioInteresse=formulario.querySelector(`input[name="interesse"][value="${dadosDoApoiador.interesse}"]`);if(radioInteresse)radioInteresse.checked=true}}catch(erro){console.error("Erro ao ler localStorage:",erro)}}function validarCampo(input){const mensagemErro=input.parentElement.querySelector(".mensagem-erro");if(!input.checkValidity()){input.classList.add("input-erro");input.classList.remove("input-sucesso");if(mensagemErro)mensagemErro.style.display="block";return false}else{input.classList.add("input-sucesso");input.classList.remove("input-erro");if(mensagemErro)mensagemErro.style.display="none";return true}}campos.forEach(campo=>{campo.addEventListener("blur",function(){validarCampo(campo)});campo.addEventListener("input",function(){if(campo.value===""){campo.classList.remove("input-erro","input-sucesso")}})});function abrirModalComprovanteFallback(){const modal=document.getElementById("modal-sucesso");if(modal){modal.classList.add("modal-ativo");modal.setAttribute("aria-hidden","false");const btnFechar=document.getElementById("btn-fechar");if(btnFechar)btnFechar.focus()}}const btnFechar=document.getElementById("btn-fechar");const modal=document.getElementById("modal-sucesso");if(btnFechar&&modal){btnFechar.addEventListener("click",()=>{modal.classList.remove("modal-ativo");modal.setAttribute("aria-hidden","true");formulario.focus()})}formulario.addEventListener("submit",function(evento){evento.preventDefault();let formularioValido=true;campos.forEach(campo=>{if(!validarCampo(campo))formularioValido=false});if(formularioValido){const agendaInteresse=formulario.querySelector('input[name="interesse"]:checked')?.value||"";const dadosDoFormulario={nome:document.getElementById("nome").value,email:document.getElementById("email").value,telefone:document.getElementById("telefone").value,nascimento:document.getElementById("nascimento").value,cpf:document.getElementById("cpf").value,cep:document.getElementById("cep").value,num_compl:document.getElementById("num_compl").value,interesse:agendaInteresse};localStorage.setItem("cadastroApoiador",JSON.stringify(dadosDoFormulario));if(typeof Swal==="function"){Swal.fire({imageUrl:"imagens/logo.png",imageWidth:250,imageAlt:"Logotipo oficial da ONG Mãos que Acolhem",title:"Cadastro Enviado!",html:`
                        <p style="color: var(--color-neutral-dark); font-size: var(--font-size-body); margin-bottom: 30px;">
                            Seus dados passaram pela validação inicial e foram salvos.
                        </p>
                        <div class="container-badges" style="display: flex; justify-content: center; gap: 10px; margin-bottom: 30px;">
                            <span class="badge badge-apoio">Apoiador Ativo</span>
                            <span class="badge badge-status">Aguardando Triagem</span>
                        </div>
                        <div class="alerta-informativo" style="text-align: left; margin: 15px auto; max-width: 100%;">
                            <strong>Informação:</strong> 
                            <p>Enviamos as instruções detalhadas diretamente para o seu e-mail cadastrado.</p>
                        </div>
                    `,confirmButtonColor:"#1a4473",confirmButtonText:"Voltar para o Início",customClass:{popup:"modal-feedback-sucesso-swal"}}).then(()=>{window.location.hash="#inicio"})}else{abrirModalComprovanteFallback()}}})};function renderInicio(){return`
        <section id="apresentacao" aria-labelledby="titulo-apresentacao">
            <h1 id="titulo-apresentacao">Transformando Vidas Através da Solidariedade</h1>
            <p>Nossa ONG atua ativamente no suporte a comunidades em situação de vulnerabilidade social. Desenvolvemos projetos focados em educação, capacitação profissional e segurança alimentar, buscando construir um futuro mais justo e com igualdade de oportunidades para todos.</p>
            <div class="imagem-institucional">
                <img src="imagens/atendimento-comunidade.jpg" alt="Voluntários da ONG sorrindo enquanto entregam materiais escolares e interagem com crianças em uma sala de aula comunitária iluminada.">
            </div>
        </section>

        <section id="contato-rapido" aria-labelledby="titulo-contato">
            <h2 id="titulo-contato">Estabeleça Contato Conosco</h2>
            <p>Quer fazer parte da nossa missão? Seja um voluntário, parceiro ou doador. Entre em contato conosco pelos canais abaixo:</p>
            <address class="dados-contato">
                <ul>
                    <li><strong>Endereço:</strong> Avenida das Mãos que Acolhem, 123 - Centro, Curitiba - PR</li>
                    <li><strong>E-mail:</strong> <a href="mailto:contato@ongmaosqueacolhem.org">contato@ongmaosqueacolhem.org</a></li>
                    <li><strong>Telefone/WhatsApp:</strong> <a href="https://wa.me" target="_blank" rel="noopener noreferrer">(41) 99999-0000</a></li>
                    <li><strong>Horário de Atendimento:</strong> Segunda a Sexta, das 09h às 18h</li>
                </ul>
            </address>
        </section>
    `}function roteador(){const container=document.getElementById("app");const hash=window.location.hash||"#inicio";const menuButton=document.getElementById("menu-button");const navPrincipal=document.getElementById("nav-principal");if(menuButton&&navPrincipal){menuButton.setAttribute("aria-expanded","false");menuButton.setAttribute("aria-label","Abrir menu de navegação");navPrincipal.classList.remove("menu-aberto")}const rotaLimpa=hash.split("?")[0];if(rotaLimpa==="#inicio"){container.innerHTML=renderInicio()}else if(rotaLimpa==="#projetos"){container.innerHTML=renderProjetos();if(hash.includes("?sec=")){const secaoId=hash.split("=")[1];const mapeamento={doacoes:"doacoes",voluntariado:"voluntariado",materiais:"doacoesmateriais"};setTimeout(()=>{const elemento=document.getElementById(mapeamento[secaoId]);if(elemento)elemento.scrollIntoView({behavior:"smooth"})},100)}}else if(rotaLimpa==="#cadastro"){container.innerHTML=renderCadastro();if(typeof window.inicializarCadastro==="function"){window.inicializarCadastro()}}else{container.innerHTML=`<h1>Página não encontrada</h1><p><a href="#inicio">Voltar ao início</a></p>`}if(container){container.focus()}}function inicializarMenuAcessivel(){const menuButton=document.getElementById("menu-button");const navPrincipal=document.getElementById("nav-principal");if(menuButton&&navPrincipal){menuButton.addEventListener("click",()=>{const estaAberto=menuButton.getAttribute("aria-expanded")==="true";menuButton.setAttribute("aria-expanded",!estaAberto);menuButton.setAttribute("aria-label",estaAberto?"Abrir menu de navegação":"Fechar menu de navegação");navPrincipal.classList.toggle("menu-aberto")})}}window.addEventListener("hashchange",roteador);window.addEventListener("DOMContentLoaded",()=>{roteador();inicializarMenuAcessivel()});function renderProjetos(){return`
        <section id="projetos" aria-labelledby="titulo-projetos">
            <h1 id="titulo-projetos">Nossas Frentes de Atuação</h1>
            <p>Conheça as ações contínuas que desenvolvemos para apoiar e empoderar nossa comunidade local.</p>
            <div class="imagem-projeto">
                <img src="imagens/rascunho-projeto.png" alt="Sobre a mesa há um papel com a logomarca sendo mãos opostas segurando um coração com traços suaves.">
            </div>			
        </section>

        <section id="doacoes" aria-labelledby="titulo-doacoes">
            <h2 id="titulo-doacoes">Como Ajudar Financeiramente</h2>
            <p>Sua doação financeira mantém nossos projetos vivos e compra suprimentos essenciais. Contribua através de nossos canais oficiais:</p>
            <ul>
                <li><strong>Chave Pix (CNPJ):</strong> 12.345.678/0001-99</li>
                <li><strong>Banco do Brasil:</strong> Agência 1234-5 | Conta Corrente: 67890-1</li>
            </ul>
            <p>
                <a href="#cadastro" aria-label="Ir para a página de cadastro para registrar uma doação recorrente">Inscreva-se para realizar uma doação recorrente</a>
            </p>
        </section>

        <section id="voluntariado" aria-labelledby="titulo-voluntariado">
            <h2 id="titulo-voluntariado">Seja um Voluntário</h2>
            <p>Doe seu tempo e suas habilidades para transformar realidades junto conosco.</p>
            <ul>
                <li><strong>Requisitos:</strong> Ter mais de 18 anos e disponibilidade de 4 horas semanais.</li>
                <li><strong>Áreas necessitadas:</strong> Reforço escolar, triagem de doações e apoio logístico.</li>
            </ul>
            <p>
                <a href="#cadastro" aria-label="Ir para a página de cadastro para preencher a ficha de voluntariado">Preencha sua ficha de inscrição para voluntariado</a>
            </p>
        </section>

        <section id="doacoesmateriais" aria-labelledby="titulo-materiais">
            <h2 id="titulo-materiais">Campanha de Contribuições Materiais</h2>
            <p>Arrecadamos permanentemente itens básicos para distribuição imediata às famílias cadastradas.</p>
            <ul>
                <li><strong>Materiais elegíveis:</strong> Alimentos não perecíveis, agasalhos, cobertores e kits de higiene.</li>
                <li><strong>Ponto de coleta:</strong> Entregas diretamente em nossa sede institucional.</li>
            </ul>
            <p>
                <a href="#inicio" aria-label="Ir para a página inicial e verificar o endereço e horários de funcionamento">Confira nosso endereço e horários de funcionamento</a>
            </p>
        </section>
    `}